  class ContextFilter { private array $defaultExclusions = [ '.env', '.env.example', '.env.local', '.env.production', '*.key', '*.pem', '*.crt', '*.p12', '*.pfx', 'credentials.json', 'secrets.json', 'passwords.txt', 'storage/logs/*', 'storage/cache/*', 'vendor/*', 'node_modules/*', '.git/*', '*.sqlite', '*.db', '*.log', '*.bin', '*.png', '*.jpg', '*.jpeg', '*.ico', '*.pdf', '*.zip', '*.gz' ]; private array $customExclusions; public function __construct(array $customExclusions = []) { $this->customExclusions = $customExclusions; } public function isExcluded(string $relativePath): bool { $path = str_replace('\\', '/', $relativePath); $allExclusions = array_merge($this->defaultExclusions, $this->customExclusions); foreach ($allExclusions as $pattern) { if ($this->matchPattern($pattern, $path)) { return true; } } $filename = strtolower(basename($path)); if (str_contains($filename, 'secret') || str_contains($filename, 'password') || str_contains($filename, 'credential')) { return true; } return false; } private function matchPattern(string $pattern, string $path): bool { if (str_ends_with($pattern, '/*')) { $dir = substr($pattern, 0, -2); return str_starts_with($path, $dir . '/') || $path === $dir; } if (str_starts_with($pattern, '*.')) { $ext = substr($pattern, 1); return str_ends_with($path, $ext); } return $path === $pattern || fnmatch($pattern, $path); } } 